package br.com.bibliotecavirtual.dao;

import br.com.bibliotecavirtual.config.ConnectionPoolConfig;
import br.com.bibliotecavirtual.model.Livro;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

/** Acesso aos dados dos livros no H2: CREATE, READ, UPDATE e DELETE. */
public class LivroDao {

    public void criarTabelaEInserirDadosIniciais() throws Exception {
        String criarTabela = "CREATE TABLE IF NOT EXISTS LIVRO (" +
                "ID INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                "TITULO VARCHAR(200) NOT NULL, AUTOR VARCHAR(160) NOT NULL, " +
                "GENERO VARCHAR(80) NOT NULL, CAPA VARCHAR(1000), SINOPSE CLOB)";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             Statement comando = conexao.createStatement()) {
            comando.execute(criarTabela);
        }
        inserirLivrosIniciaisSeVazio();
    }

    private void inserirLivrosIniciaisSeVazio() throws Exception {
        String contar = "SELECT COUNT(*) FROM LIVRO";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             Statement comando = conexao.createStatement();
             ResultSet resultado = comando.executeQuery(contar)) {
            if (resultado.next() && resultado.getInt(1) > 0) return;
        }

        Livro[] iniciais = {
            new Livro("Dom Casmurro", "Machado de Assis", "Clássico", "", "Bentinho relembra a juventude e o casamento com Capitu, tentando provar uma traição que talvez só exista no ciúme dele."),
            new Livro("A Hora da Estrela", "Clarice Lispector", "Contemporâneo", "", "Macabéa é uma moça pobre do Nordeste que vive no Rio de Janeiro como datilógrafa. A história mostra como a sociedade ignora pessoas como ela."),
            new Livro("Capitães da Areia", "Jorge Amado", "Regionalismo", "", "Um grupo de meninos abandonados vive em um trapiche em Salvador e sobrevive de pequenos furtos. O livro retrata a infância nas ruas e a desigualdade social."),
            new Livro("Grande Sertão: Veredas", "Guimarães Rosa", "Regionalismo", "", "Riobaldo conta sua vida no sertão, as batalhas entre bandos e a amizade com Diadorim, enquanto questiona o bem, o mal e o destino."),
            new Livro("Memórias Póstumas de Brás Cubas", "Machado de Assis", "Clássico", "", "Um narrador já falecido conta sua vida com ironia e critica os costumes da sociedade brasileira do século XIX."),
            new Livro("O Cortiço", "Aluísio Azevedo", "Clássico", "", "A vida dos moradores de um cortiço no Rio de Janeiro revela conflitos sociais, ambição e desigualdade."),
            new Livro("Vidas Secas", "Graciliano Ramos", "Regionalismo", "", "Uma família de retirantes enfrenta a seca, a pobreza e a luta pela sobrevivência no sertão nordestino."),
            new Livro("Iracema", "José de Alencar", "Romance", "", "O romance indianista acompanha Iracema e Martim e apresenta uma narrativa simbólica sobre a formação do Ceará."),
            new Livro("Quarto de Despejo", "Carolina Maria de Jesus", "Memórias", "", "Diário de uma catadora de papel que registra a fome, a criação dos filhos e a vida na favela do Canindé, em São Paulo."),
            new Livro("Macunaíma", "Mário de Andrade", "Modernismo", "", "A história mistura lendas indígenas, folclore e crítica ao Brasil ao acompanhar as aventuras de Macunaíma."),
            new Livro("Torto Arado", "Itamar Vieira Junior", "Contemporâneo", "", "As irmãs Bibiana e Belonísia crescem em uma fazenda no interior da Bahia, onde suas famílias trabalham sem possuir a terra."),
            new Livro("O Alienista", "Machado de Assis", "Clássico", "", "O médico Simão Bacamarte abre um hospício em Itaguaí e passa a questionar os limites entre loucura e normalidade.")
        };
        for (Livro livro : iniciais) inserir(livro);
    }

    public List<Livro> listarTodos() throws Exception {
        List<Livro> livros = new ArrayList<>();
        String sql = "SELECT ID, TITULO, AUTOR, GENERO, CAPA, SINOPSE FROM LIVRO ORDER BY TITULO";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             PreparedStatement comando = conexao.prepareStatement(sql);
             ResultSet resultado = comando.executeQuery()) {
            while (resultado.next()) livros.add(mapear(resultado));
        }
        return livros;
    }

    public Livro buscarPorId(int id) throws Exception {
        String sql = "SELECT ID, TITULO, AUTOR, GENERO, CAPA, SINOPSE FROM LIVRO WHERE ID = ?";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             PreparedStatement comando = conexao.prepareStatement(sql)) {
            comando.setInt(1, id);
            try (ResultSet resultado = comando.executeQuery()) {
                if (resultado.next()) return mapear(resultado);
            }
        }
        return null;
    }

    public void inserir(Livro livro) throws Exception {
        String sql = "INSERT INTO LIVRO (TITULO, AUTOR, GENERO, CAPA, SINOPSE) VALUES (?, ?, ?, ?, ?)";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             PreparedStatement comando = conexao.prepareStatement(sql)) {
            preencherParametros(comando, livro);
            comando.executeUpdate();
        }
    }

    public boolean atualizar(Livro livro) throws Exception {
        String sql = "UPDATE LIVRO SET TITULO = ?, AUTOR = ?, GENERO = ?, CAPA = ?, SINOPSE = ? WHERE ID = ?";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             PreparedStatement comando = conexao.prepareStatement(sql)) {
            preencherParametros(comando, livro);
            comando.setInt(6, livro.getId());
            return comando.executeUpdate() > 0;
        }
    }

    public boolean excluir(int id) throws Exception {
        String sql = "DELETE FROM LIVRO WHERE ID = ?";
        try (Connection conexao = ConnectionPoolConfig.getConnection();
             PreparedStatement comando = conexao.prepareStatement(sql)) {
            comando.setInt(1, id);
            return comando.executeUpdate() > 0;
        }
    }

    private void preencherParametros(PreparedStatement comando, Livro livro) throws Exception {
        comando.setString(1, livro.getTitulo().trim());
        comando.setString(2, livro.getAutor().trim());
        comando.setString(3, livro.getGenero().trim());
        comando.setString(4, livro.getCapa() == null ? "" : livro.getCapa().trim());
        comando.setString(5, livro.getSinopse() == null ? "" : livro.getSinopse().trim());
    }

    private Livro mapear(ResultSet resultado) throws Exception {
        return new Livro(resultado.getInt("ID"), resultado.getString("TITULO"),
                resultado.getString("AUTOR"), resultado.getString("GENERO"),
                resultado.getString("CAPA"), resultado.getString("SINOPSE"));
    }
}
